inline void expression(Document& doc){for(unsigned z=0;z<2;++z){view(doc,z);for(unsigned i=0;i<3;++i){const Point p{.2+.5*i,.2+.3*i+.1*z};const auto id=doc.add_detection(Roi::points({p}),"Spot");doc.set_object_properties(id,std::make_shared<ObjectProperties>(std::map<std::string,std::string>{{"omics.profile","qpx.spatial-counts/1"},{"omics.matrix_sha256",std::string(64,'a')},{"omics.features_sha256",std::string(64,'b')},{"omics.positions_sha256",std::string(64,'c')},{"omics.observation_id","spot"+std::to_string(z)+"-"+std::to_string(i)}},std::map<std::string,double>{{"omics.count:G",double(i+1)}}));}}view(doc,0);}
inline Point drawn_center(ImDrawList* draw,int begin,ImU32 color){Point center{};std::size_t n=0;for(int i=begin;i<draw->VtxBuffer.Size;++i)if(draw->VtxBuffer[i].col==color){center.x+=draw->VtxBuffer[i].pos.x;center.y+=draw->VtxBuffer[i].pos.y;++n;}check(n>0,"Expected drawn positions absent");return {center.x/n,center.y/n};}
inline void position_close(Point a,Point b,const char* message){check(std::abs(a.x-b.x)<.65 && std::abs(a.y-b.y)<.65,std::string(message)+" actual="+std::to_string(a.x)+","+std::to_string(a.y)+" expected="+std::to_string(b.x)+","+std::to_string(b.y));}
