inline void polygon(const std::filesystem::path& dir){
    const auto signal=source_file(dir,"polygon.ome.tif");auto project=std::make_shared<Project>();auto doc=std::make_shared<Document>(open_tiff(signal.u8string()));project->add_document(doc,"Polygon",signal.u8string());auto o=::options(dir,"polygon-scope","annotations");o.width=1600;o.height=1200;o.settle_tiles=false;
    o.inputs={key(3,GuiInputKind::PolygonKey)};int frame=6;for(Point p:std::vector<Point>{{.2,.2},{.7,.2},{.7,.7}}){auto e=key(frame,GuiInputKind::LeftDown);e.target=GuiInputTarget::Image;e.x=p.x;e.y=p.y;o.inputs.push_back(e);e.frame++;e.kind=GuiInputKind::LeftUp;o.inputs.push_back(e);frame+=3;}
    dispatch_checks::TraceScope observed;int stage=0;bool scale=false;const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(25);
    observed.workflow.trace.before_frame=[&](int){check(std::chrono::steady_clock::now()<deadline,"Polygon scope deadline");};
    observed.trace.replay_input=[&](const auto& emit){if(scale){auto e=key(0,GuiInputKind::SetUiScale);e.x=1.25;emit(e);scale=false;}};
    observed.trace.after_frame=[&](const auto&,const auto&){const auto n=observed.trace.draft_points;if(stage==0){if(n!=3)return;doc->add_rectangle({0,0,.1,.1});++stage;return;}if(stage==1){check(n==3,"Document edit dropped polygon draft");view(*doc,0,true);++stage;return;}if(stage==2){check(n==3,"View replacement dropped polygon draft");view(*doc,1);++stage;return;}if(stage==3){check(n==0,"Polygon draft drawn on another plane");view(*doc,0);++stage;return;}if(stage==4){check(n==3,"Plane return lost polygon draft");scale=true;++stage;return;}if(stage==5){check(n==3,"UI scaling dropped polygon draft");++stage;return;}check(n==3,"Scaled polygon draft did not survive");observed.trace.end_session=true;};
    const auto report=run_project_gui(project,20000,"",o);check(stage==6 && observed.trace.end_session && doc->object_count()==1 && report.ui_overflow_items==0,"Polygon scope scene incomplete or mutated its draft");
    std::cout<<"Polygon draft: document edit, view replacement, plane hide/return and UI scale retain the draft without adding it\n";
}
